// Parse Message Code Node — FIRST node in JS-01v2 (Design v1.1.8 / Req 27.1, 27.3).
// Extracts phone + text from the WhatsApp webhook payload and assigns ONE trace_id
// (UUIDv7) per inbound message, propagated on $json.trace_id so every downstream node
// (Upsert Session, Prepare Context, CEO Router, Logger) and every outbound Vercel /api
// call (X-Trace-Id header) carries it.
//
// Self-contained (n8n sandbox: no import/require). UUIDv7 logic is ported inline from
// src/lib/trace/uuid7.ts; inbound-reuse mirrors src/lib/trace/extract.ts: if the upstream
// webhook already supplied a valid UUIDv7 trace id, reuse it so the trace stays continuous,
// otherwise mint a fresh one.

const UUID7_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

function isUuid7(s) {
  return typeof s === 'string' && UUID7_RE.test(s);
}

function randomBytes(out) {
  const g = (typeof globalThis !== 'undefined') ? globalThis : {};
  if (g.crypto && typeof g.crypto.getRandomValues === 'function') {
    g.crypto.getRandomValues(out);
    return out;
  }
  for (let i = 0; i < out.length; i++) out[i] = Math.floor(Math.random() * 256);
  return out;
}

const HEX = [];
for (let i = 0; i < 256; i++) HEX.push((i + 256).toString(16).slice(1));

function uuid7(now) {
  if (now == null) now = Date.now();
  const b = new Uint8Array(16);
  const ts = Math.max(0, Math.floor(now));
  b[0] = Math.floor(ts / 1099511627776) & 255;
  b[1] = Math.floor(ts / 4294967296) & 255;
  b[2] = Math.floor(ts / 16777216) & 255;
  b[3] = Math.floor(ts / 65536) & 255;
  b[4] = Math.floor(ts / 256) & 255;
  b[5] = ts & 255;
  const rand = randomBytes(new Uint8Array(10));
  for (let i = 0; i < 10; i++) b[6 + i] = rand[i];
  b[6] = (b[6] & 15) | 112;
  b[8] = (b[8] & 63) | 128;
  return (
    HEX[b[0]] + HEX[b[1]] + HEX[b[2]] + HEX[b[3]] + '-' +
    HEX[b[4]] + HEX[b[5]] + '-' +
    HEX[b[6]] + HEX[b[7]] + '-' +
    HEX[b[8]] + HEX[b[9]] + '-' +
    HEX[b[10]] + HEX[b[11]] + HEX[b[12]] + HEX[b[13]] + HEX[b[14]] + HEX[b[15]]
  );
}

// Read an inbound trace id case-insensitively from headers / body (extract.ts semantics).
function inboundTraceId(m) {
  const out = [];
  const headers = m.headers || m.header || (m.body && m.body.headers);
  if (headers && typeof headers === 'object') {
    for (const k of Object.keys(headers)) {
      if (k.toLowerCase() === 'x-trace-id') out.push(headers[k]);
    }
  }
  out.push(m.trace_id, m.body && m.body.trace_id);
  for (const c of out) {
    const v = (c == null) ? '' : String(c).trim();
    if (isUuid7(v)) return v;
  }
  return null;
}

const msg = $input.first().json;
const body = msg.body || msg.entry?.[0]?.changes?.[0]?.value?.messages?.[0] || {};
const rawText = body.text?.body || body.body || body.button?.text || '';
const phone = body.from || msg.from || '';
const trace_id = inboundTraceId(msg) || uuid7();

return [{ json: { phone, message: { text: (rawText || '').toLowerCase(), original_text: rawText }, trace_id, raw: msg } }];

// PLACEHOLDER — injected at deploy time from n8n-workflows/code-nodes/prepare-context.js
// (deploy-workflows-v2.js CODE_NODE_INJECTIONS map: 'Prepare Context' -> prepare-context.js)
