// PLACEHOLDER — injected at deploy time from n8n-workflows/code-nodes/ceo-router.js
// (deploy-workflows-v2.js CODE_NODE_INJECTIONS map: 'CEO Router' -> ceo-router.js)
// Output contract consumed by Switch Node: $json.agent in {complaint,blood,donor,info,welcome}
return [{ json: { ...$json, agent: 'welcome', reason: 'placeholder' } }];

// PLACEHOLDER — injected at deploy time from n8n-workflows/code-nodes/gemini-substitute.js
// (deploy-workflows-v2.js CODE_NODE_INJECTIONS map: 'Gemini Check - Complaint' -> gemini-substitute.js)
// Task 27.4 — Design §v1.1.10 Circuit Breakers (Req 29.2, 29.3)
// Reads circuit_state.gemini; if open, sets $json.gemini_open=true and $json.reply=<template>.
// The downstream IF node routes to Send Reply (open) or Complaint Agent (closed).
